test('invoiceTotals with multiple lines, discounts and different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 5, vatRate: 21 },  // subtotal 100000, discount 5000, vat (95000*21/100)=19950
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 9 },  // subtotal 100000, discount 10000, vat (90000*9/100)=8100
      { qty: 100, unitPrice: 1000, vatRate: 0 },                       // subtotal 100000, discount 0, vat 0
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 300000);
  assert.equal(totals.discount, 15000);
